type Authorizer interface {
    Authorize(ctx context.Context, a Action, r Resource) error
}
func Guard(authz Authorizer, next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        if err := authz.Authorize(r.Context(), actionOf(r), resourceOf(r)); err != nil {
            auditDenied(r.Context(), err)
            http.Error(w, "forbidden", http.StatusForbidden)  // deny by default
            return
        }
        next.ServeHTTP(w, r)
    })
}
